from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG = -10**18  # sentinel for unreachable states

        # dp[i][j][k] = max profit reaching cell (i,j) having used k neutralizations
        dp = [[[NEG] * 3 for _ in range(n)] for _ in range(m)]

        # Handle starting cell (0,0)
        val0 = coins[0][0]
        if val0 >= 0:
            for k in range(3):
                dp[0][0][k] = val0
        else:
            # take the loss
            dp[0][0][0] = val0
            # neutralize once
            dp[0][0][1] = 0
            # cannot use two neutralizations on a single cell

        # Fill the rest of the grid
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue  # already initialized
                val = coins[i][j]

                # best previous values from top and left
                best_top = dp[i-1][j] if i > 0 else [NEG]*3
                best_left = dp[i][j-1] if j > 0 else [NEG]*3
                best_prev = [max(best_top[k], best_left[k]) for k in range(3)]

                if val >= 0:
                    for k in range(3):
                        if best_prev[k] != NEG:
                            dp[i][j][k] = best_prev[k] + val
                else:  # val < 0, robber present
                    for k in range(3):
                        # Option 1: let the robber steal
                        opt1 = best_prev[k] + val if best_prev[k] != NEG else NEG
                        # Option 2: neutralize this robber (if we have unused neutralization)
                        opt2 = NEG
                        if k > 0 and best_prev[k-1] != NEG:
                            opt2 = best_prev[k-1]  # add 0
                        dp[i][j][k] = max(opt1, opt2)

        return max(dp[m-1][n-1])
