from decimal import Decimal, ROUND_FLOOR, ROUND_CEILING

def closest_integer(value):
    """
    Return the integer closest to the numeric string `value`.
    If the value is exactly halfway between two integers, round away from zero.
    """
    dec = Decimal(value)

    # Compute floor and ceil as Decimals
    floor_dec = dec.to_integral_value(rounding=ROUND_FLOOR)
    ceil_dec = dec.to_integral_value(rounding=ROUND_CEILING)

    # If the value is already an integer, just return it
    if floor_dec == ceil_dec:
        return int(floor_dec)

    # Distances to floor and ceil
    diff_floor = dec - floor_dec
    diff_ceil = ceil_dec - dec

    # Compare absolute differences
    if diff_floor < diff_ceil:
        return int(floor_dec)
    if diff_ceil < diff_floor:
        return int(ceil_dec)

    # Tie case: choose the integer farther from zero (greater absolute value)
    if abs(int(floor_dec)) > abs(int(ceil_dec)):
        return int(floor_dec)
    else:
        return int(ceil_dec)
