from typing import List, Dict

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k > n or n == 0:
            return -1

        # Count how many subarrays of size k each number appears in
        count: Dict[int, int] = {}
        for start in range(n - k + 1):
            sub = nums[start:start + k]
            seen = set(sub)               # avoid double counting in the same subarray
            for val in seen:
                count[val] = count.get(val, 0) + 1

        # Find the largest number that appears in exactly one subarray
        max_val = -1
        for val, cnt in count.items():
            if cnt == 1 and val > max_val:
                max_val = val

        return max_val
