def is_simple_power(x, n):
    """
    Return True if there exists an integer k such that n**k == x,
    otherwise False.
    """
    # Special cases
    if n == 0:
        return x == 0
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1 or x == -1

    power = 1
    while abs(power) <= abs(x):
        if power == x:
            return True
        power *= n
    return False
