from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Convert event timestamps to integers for easier handling
        # Sort events by timestamp, with OFFLINE events processed before MESSAGE at same timestamp
        def sort_key(ev):
            t = int(ev[1])
            return (t, 0 if ev[0] == "OFFLINE" else 1)

        events_sorted = sorted(events, key=sort_key)

        # Track when each user will automatically come back online
        offline_until = {}  # user_id -> timestamp when they become online again

        mentions = [0] * numberOfUsers

        for ev in events_sorted:
            t = int(ev[1])
            if ev[0] == "OFFLINE":
                uid = int(ev[2])
                offline_until[uid] = t + 60
            else:  # MESSAGE
                tokens = ev[2].split()
                for tok in tokens:
                    if tok == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif tok == "HERE":
                        for i in range(numberOfUsers):
                            # User is online if they are not currently offline
                            if offline_until.get(i, 0) <= t:
                                mentions[i] += 1
                    else:  # id<number>
                        if tok.startswith("id"):
                            uid = int(tok[2:])
                            mentions[uid] += 1
                        # Any unexpected token is ignored (not required by spec)
        return mentions
