class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Helper to generate all substrings (including the empty string)
        def all_substrings(st: str):
            n = len(st)
            subs = set()
            subs.add("")  # empty substring
            for i in range(n):
                for j in range(i, n):
                    subs.add(st[i:j+1])
            return subs

        subs_s = all_substrings(s)
        subs_t = all_substrings(t)

        best_len = 0
        # Try every combination of substring from s and substring from t
        for sub_s in subs_s:
            for sub_t in subs_t:
                candidate = sub_s + sub_t
                l = len(candidate)
                if l <= best_len:
                    continue  # no need to check
                if candidate == candidate[::-1]:
                    best_len = l

        return best_len
```

