from typing import List
import math

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        """
        For each group value, find the index of the smallest j such that
        elements[j] divides the group. Return -1 if none exists.
        """
        # Map each element value to the smallest index that has that value
        min_index_for_value = {}
        for idx, val in enumerate(elements):
            if val not in min_index_for_value or idx < min_index_for_value[val]:
                min_index_for_value[val] = idx

        result = []
        for g in groups:
            best = None
            sqrt_g = int(math.isqrt(g))
            for d in range(1, sqrt_g + 1):
                if g % d == 0:
                    # divisor d
                    idx = min_index_for_value.get(d)
                    if idx is not None:
                        if best is None or idx < best:
                            best = idx
                    # counterpart divisor g//d
                    other = g // d
                    if other != d:
                        idx = min_index_for_value.get(other)
                        if idx is not None:
                            if best is None or idx < best:
                                best = idx
            result.append(best if best is not None else -1)
        return result
